package pagos;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import config.ConfiguracionMercadoPago;import java.math.BigDecimal;import java.net.URI;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
public class MercadoPagoPasarela implements PasarelaPagoOnline {private final ConfiguracionMercadoPago config;private final MercadoPagoHttpTransport http;private final ObjectMapper json;public MercadoPagoPasarela(ConfiguracionMercadoPago c){this(c,new JdkMercadoPagoHttpTransport(),new ObjectMapper().findAndRegisterModules());}public MercadoPagoPasarela(ConfiguracionMercadoPago c,MercadoPagoHttpTransport h,ObjectMapper j){if(c==null||!c.disponible()||h==null||j==null)throw new IllegalArgumentException("Mercado Pago requiere configuración, transporte y JSON.");config=c;http=h;json=j;}public boolean disponible(){return true;}public CheckoutCreado crearCheckout(SolicitudCheckout s){try{ObjectNode body=json.createObjectNode();ArrayNode items=body.putArray("items");ObjectNode item=items.addObject();item.put("id","senia-reserva-"+s.reservaId());item.put("title",s.descripcion()==null?"Seña de reserva":s.descripcion());item.put("quantity",1);item.put("currency_id",s.moneda());item.put("unit_price",s.importe());body.put("external_reference",s.referencia());body.put("notification_url",s.notificacionUrl().toString());body.put("auto_return","approved");ObjectNode back=body.putObject("back_urls");back.put("success",s.retornoExitoso().toString());back.put("pending",s.retornoPendiente().toString());back.put("failure",s.retornoFallido().toString());if(s.vencimiento()!=null){body.put("expires",true);body.put("expiration_date_to",s.vencimiento().atZone(ZoneId.systemDefault()).format(DateTimeFormatter.ISO_OFFSET_DATE_TIME));}var r=http.ejecutar("POST",config.apiBaseUrl().resolve("/checkout/preferences"),headers(s.claveIdempotencia()),json.writeValueAsString(body));if(!r.exitosa())throw error(r);JsonNode out=json.readTree(r.cuerpo());String id=text(out,"id"),url=text(out,"init_point");if(id==null||url==null)throw new IllegalStateException("Mercado Pago devolvió una preferencia incompleta.");return new CheckoutCreado(id,URI.create(url),s.vencimiento(),s.referencia());}catch(IllegalStateException e){throw e;}catch(Exception e){throw new IllegalStateException("No se pudo crear el checkout de Mercado Pago.",e);}}public PagoExterno consultarPago(String id){if(id==null||id.isBlank())throw new IllegalArgumentException("El pago externo es obligatorio.");try{var r=http.ejecutar("GET",config.apiBaseUrl().resolve("/v1/payments/"+id.trim()),headers(null),null);if(!r.exitosa())throw error(r);JsonNode n=json.readTree(r.cuerpo());return new PagoExterno(text(n,"id"),text(n,"external_reference"),text(n,"status"),text(n,"status_detail"),decimal(n,"transaction_amount"),text(n,"currency_id"),fecha(text(n,"date_approved")));}catch(IllegalStateException e){throw e;}catch(Exception e){throw new IllegalStateException("No se pudo consultar el pago de Mercado Pago.",e);}}public java.util.List<PagoExterno> buscarPagosPorReferencia(String referencia){if(referencia==null||referencia.isBlank())return java.util.List.of();try{String valor=java.net.URLEncoder.encode(referencia.trim(),java.nio.charset.StandardCharsets.UTF_8);var r=http.ejecutar("GET",config.apiBaseUrl().resolve("/v1/payments/search?external_reference="+valor),headers(null),null);if(!r.exitosa())throw error(r);JsonNode root=json.readTree(r.cuerpo()),results=root.path("results");if(!results.isArray())return java.util.List.of();java.util.List<PagoExterno> out=new java.util.ArrayList<>();for(JsonNode n:results)out.add(new PagoExterno(text(n,"id"),text(n,"external_reference"),text(n,"status"),text(n,"status_detail"),decimal(n,"transaction_amount"),text(n,"currency_id"),fecha(text(n,"date_approved"))));return java.util.List.copyOf(out);}catch(IllegalStateException e){throw e;}catch(Exception e){throw new IllegalStateException("No se pudieron conciliar los pagos de Mercado Pago.",e);}}private Map<String,String> headers(String idem){Map<String,String> h=new LinkedHashMap<>();h.put("Authorization","Bearer "+config.accessToken());h.put("Content-Type","application/json");h.put("Accept","application/json");if(idem!=null&&!idem.isBlank())h.put("X-Idempotency-Key",idem);return h;}private IllegalStateException error(MercadoPagoHttpTransport.Respuesta r){String detalle="HTTP "+r.estado();try{JsonNode n=json.readTree(r.cuerpo());String m=text(n,"message");if(m!=null)detalle+=" - "+m;}catch(Exception ignored){}return new IllegalStateException("Mercado Pago rechazó la operación ("+detalle+").");}private String text(JsonNode n,String k){JsonNode v=n.get(k);return v==null||v.isNull()?null:v.asText();}private BigDecimal decimal(JsonNode n,String k){JsonNode v=n.get(k);return v==null||v.isNull()?null:v.decimalValue();}private LocalDateTime fecha(String v){if(v==null||v.isBlank())return null;try{return OffsetDateTime.parse(v).toLocalDateTime();}catch(Exception e){return null;}}}
